const input = $input.first()?.json || {};

const stdout = String(input.stdout ?? input.data ?? '');
const stderr = String(input.stderr ?? '');
const exitCode = Number(input.exitCode ?? input.code ?? 0);

const EXPECTED_DBS = [
  'coc_crystal',
  'coc_isentia_anz',
  'coc_kmitaly',
  'coc_nla',
  'coc_nzg_test',
  'coc_opoint',
  'coc_rdl',
  'coc_volocom',
  'emslive',
  'glpidbdumpadmin',
  'glpidbdump_electrical',
  'glpinewdbdump',
  'icp_jstor_aos',
  'invoicepro_live',
  'jbooks',
  'rdl_dmsworkflow'
];

const BACKUP_DIR =
  '/mnt/isolated-db-backup/isolated_DBbackup/itshare/Telecom-DB-Backup/aclsys/chennai_db';

function norm(value) {
  return String(value || '')
    .trim()
    .toLowerCase();
}

function getISTDate() {

  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kolkata',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());

  const p = Object.fromEntries(
    parts.map(x => [x.type, x.value])
  );

  return `${p.year}-${p.month}-${p.day}`;
}

function parseDateFromFilename(filename) {

  const name = String(filename);

  // YYYY-MM-DD
  let m = name.match(
    /(\d{4})-(\d{2})-(\d{2})/
  );

  if (m) {
    return `${m[1]}-${m[2]}-${m[3]}`;
  }

  // DD-MM-YYYY
  m = name.match(
    /(\d{2})-(\d{2})-(\d{4})/
  );

  if (m) {
    return `${m[3]}-${m[2]}-${m[1]}`;
  }

  return null;
}

function parseDbPrefix(filename) {

  let name = String(filename);

  // Remove compression extension
  name = name.replace(
    /\.sql\.(zip|gz)$/i,
    ''
  );

  // YYYY-MM-DD
  let m = name.match(
    /^(.*?)(\d{4}-\d{2}-\d{2})/
  );

  if (m) {
    return m[1]
      .replace(/[_-]+$/, '')
      .toLowerCase();
  }

  // DD-MM-YYYY
  m = name.match(
    /^(.*?)(\d{2}-\d{2}-\d{4})/
  );

  if (m) {
    return m[1]
      .replace(/[_-]+$/, '')
      .toLowerCase();
  }

  return null;
}

const today = getISTDate();

const mountMatch =
  stdout.match(/MOUNT_STATUS=(\w+)/);

const mountStatus =
  mountMatch
    ? mountMatch[1].toUpperCase()
    : 'UNKNOWN';

const dirMatch =
  stdout.match(/BACKUP_DIR_STATUS=(\w+)/);

const backupDirStatus =
  dirMatch
    ? dirMatch[1].toUpperCase()
    : 'UNKNOWN';

const fileSectionMatch =
  stdout.match(
    /BACKUP_FILES_BEGIN\s*([\s\S]*?)\s*BACKUP_FILES_END/
  );

const fileSection =
  fileSectionMatch
    ? fileSectionMatch[1]
    : '';

const files = fileSection
  .split(/\r?\n/)
  .map(x => x.trim())
  .filter(Boolean);

const fileRecords = files
  .filter(file =>
    /\.sql\.(zip|gz)$/i.test(file)
  )
  .map(filename => ({
    filename,
    database: parseDbPrefix(filename),
    backup_date: parseDateFromFilename(filename)
  }));

const todayFiles = fileRecords.filter(
  x =>
    x.backup_date === today &&
    x.database
);

const todayByDatabase = new Map();

for (const file of todayFiles) {

  const db = norm(file.database);

  if (!todayByDatabase.has(db)) {
    todayByDatabase.set(db, []);
  }

  todayByDatabase
    .get(db)
    .push(file.filename);
}

const databaseResults = EXPECTED_DBS.map(database => {

  const matches =
    todayByDatabase.get(norm(database)) || [];

  return {

    database,

    status:
      matches.length > 0
        ? 'BACKUP_PRESENT'
        : 'BACKUP_MISSING',

    backup_count_today:
      matches.length,

    backup_files_today:
      matches,

    latest_backup_file:
      matches.length
        ? matches[matches.length - 1]
        : null
  };
});

const missingDatabases =
  databaseResults.filter(
    x => x.status === 'BACKUP_MISSING'
  );

const presentDatabases =
  databaseResults.filter(
    x => x.status === 'BACKUP_PRESENT'
  );

let healthStatus = 'HEALTHY';

if (mountStatus !== 'OK') {

  healthStatus =
    'CRITICAL - HDD MOUNT NOT AVAILABLE';

}
else if (backupDirStatus !== 'OK') {

  healthStatus =
    'CRITICAL - BACKUP DIRECTORY NOT AVAILABLE';

}
else if (missingDatabases.length > 0) {

  healthStatus =
    'WARNING - DATABASE BACKUP(S) MISSING';
}

const coverage =
  (
    presentDatabases.length /
    EXPECTED_DBS.length
  ) * 100;

return [
  {
    json: {

      run_at:
        new Date().toISOString(),

      check_date_ist:
        today,

      hostname:
        input.hostname || null,

      backup_dir:
        BACKUP_DIR,

      mount_status:
        mountStatus,

      backup_dir_status:
        backupDirStatus,

      ssh_exit_code:
        exitCode,

      ssh_stderr:
        stderr,

      health_status:
        healthStatus,

      expected_database_count:
        EXPECTED_DBS.length,

      backup_present_count:
        presentDatabases.length,

      backup_missing_count:
        missingDatabases.length,

      coverage_percent:
        Number(coverage.toFixed(2)),

      expected_databases:
        EXPECTED_DBS,

      database_results:
        databaseResults,

      missing_databases:
        missingDatabases.map(
          x => x.database
        ),

      present_databases:
        presentDatabases.map(
          x => x.database
        ),

      today_backup_files:
        todayFiles.map(
          x => x.filename
        )
    }
  }
];
